'use strict';
const $ = (selector, scope = document) => scope.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const icons = {
  mcp:'<path d="M8 3v5m8-5v5M5 8h14v3a7 7 0 0 1-7 7v4m-7-11h14"/>',
  overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  models:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>',
  discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5 5-3Z"/>',
  downloads:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v5h16v-5"/>',
  studio:'<path d="m4 20 12-12m-1-4 1-2 1 2 2 1-2 1-1 2-1-2-2-1 2-1ZM5 5l1-2 1 2 2 1-2 1-1 2-1-2-2-1 2-1Zm12 12 1-2 1 2 2 1-2 1-1 2-1-2-2-1 2-1Z"/>',
  chat:'<path d="M21 11a9 9 0 0 1-9 9c-2 0-3.5-.5-5-1.5L3 21l1.5-4A9 9 0 1 1 21 11Z"/><path d="M8 11h.01M12 11h.01M16 11h.01"/>',
  benchmark:'<path d="M4 19V9m5 10V5m5 14v-7m5 7V3M2 21h20"/>',
  settings:'<path d="m10 3-1 3-3 1-2-1-2 4 2 2v2l-2 2 2 4 3-1 2 1 1 3h4l1-3 2-1 3 1 2-4-2-2v-2l2-2-2-4-3 1-2-1-1-3Z"/><circle cx="12" cy="13" r="3"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', close:'<path d="m6 6 12 12M18 6 6 18"/>', search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>', refresh:'<path d="M20 7a8 8 0 0 0-14-2L3 8m0-5v5h5m-4 9a8 8 0 0 0 14 2l3-3m0 5v-5h-5"/>', arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>', external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>', info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>', trash:'<path d="M3 6h18M9 6V3h6v3m-10 0 1 15h12l1-15M10 10v7m4-7v7"/>', copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>', stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>', play:'<path d="m7 3 14 9-14 9V3Z"/>', cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><rect x="9" y="9" width="6" height="6"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>', memory:'<rect x="3" y="6" width="18" height="12" rx="2"/><path d="M6 10h3v4H6zm9 0h3v4h-3zM6 18v3m4-3v3m4-3v3m4-3v3"/>', disk:'<path d="m5 3-3 13v5h20v-5L19 3H5ZM2 16h20M17 19h.01"/>', shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7l1-8Z"/>', logout:'<path d="M9 3H3v18h6M9 12h12m-4-4 4 4-4 4"/>', attach:'<path d="m8 13 7-7a3 3 0 0 1 4 4L9 20a5 5 0 0 1-7-7L13 2"/>', send:'<path d="m3 3 19 9-19 9 4-9-4-9Zm4 9h15"/>', more:'<circle cx="4" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="20" cy="12" r="1"/>', edit:'<path d="m16 3 5 5L8 21H3v-5L16 3ZM13 6l5 5"/>', check:'<path d="m5 12 4 4L19 6"/>', book:'<path d="M5 3h14v19l-7-5-7 5V3Z"/>'
};
const icon = (name, className='') => `<svg class="icon ${className}" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.info}</svg>`;
const pages = ['overview','models','discover','downloads','studio','chat','benchmark','mcp','settings'];
const labels = {overview:'Overview',models:'Models',discover:'Discover',downloads:'Downloads',studio:'Model Studio',chat:'Chat',benchmark:'Benchmark',mcp:'MCP connections',settings:'Settings'};
const state = {csrf:null,authenticated:false,branding:{title:'Spark Ollama Manager',subtitle:'Your private AI control room'},data:null,status:null,page:pages.includes(location.hash.slice(1))?location.hash.slice(1):'overview',modelSearch:'',modelSort:'name',studioTab:'create',chatId:null,chatModel:'',chatDraft:'',resetRender:false,messages:[],attachments:[],streaming:false,chatController:null,systemPrompt:'',chatOptions:{temperature:.7,num_ctx:4096},pollBusy:false,installPrompt:null,mcpSelected:[],toolEvents:[],mcpTests:{},mcpTools:{},bookmarks:readLocal('spark-bookmarks',[]),presets:readLocal('spark-presets',[])};
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key)) || fallback}catch{return fallback}}
function saveLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('This browser could not save your preferences.',true)}}
function bytes(n){if(n===undefined||n===null||!Number.isFinite(Number(n)))return '—';n=Number(n);if(n===0)return '0 B';const units=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<4){n/=1024;i++}return `${n.toFixed(i<2?0:1)} ${units[i]}`}
function date(value){if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString(undefined,{month:'short',day:'numeric'})}
function elapsed(seconds){if(!Number.isFinite(Number(seconds)))return '—';seconds=Number(seconds);return seconds>=86400?`${Math.floor(seconds/86400)}d ${Math.floor(seconds%86400/3600)}h`:seconds>=3600?`${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m`:`${Math.floor(seconds/60)}m`}
function server(){return state.data?.servers.find(s=>s.id===state.data.activeServerId)}
function sid(){return state.data?.activeServerId}
function models(){return state.status?.models||[]}
function modelName(m){return m.name||m.model||''}
function modelOptions(selected=''){return '<option value="">Select a local model</option>'+models().map(m=>`<option value="${esc(modelName(m))}"${selected===modelName(m)?' selected':''}>${esc(modelName(m))}</option>`).join('')}
function jobs(type){return (state.data?.jobs||[]).filter(j=>(!type||j.type===type)&&j.serverId===sid()).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))}
function activeJobs(){return jobs().filter(j=>j.status==='queued'||j.status==='running')}
function empty(title,description,action='',ico='models'){return `<div class="empty">${icon(ico)}<strong>${esc(title)}</strong><p>${esc(description)}</p>${action}</div>`}
function btn(text,action,ico='',kind='',data=''){return `<button class="btn ${kind}" type="button" data-action="${action}" ${text?'':`aria-label="${esc(action==='stop-chat'?'Stop generation':ico)}"`} ${data}>${ico?icon(ico):''}${esc(text)}</button>`}
function actionIcon(title,action,ico,data='',danger=false){return `<button type="button" class="icon-btn ${danger?'danger':''}" aria-label="${esc(title)}" title="${esc(title)}" data-action="${action}" ${data}>${icon(ico)}</button>`}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`toast show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000)}
async function api(path,body,method){const options={credentials:'same-origin',cache:'no-store',headers:{}};if(body!==undefined){options.method=method||'POST';options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}else options.method=method||'GET';if(options.method!=='GET')options.headers['X-CSRF-Token']=state.csrf||'';const response=await fetch(path,options);let data;try{data=await response.json()}catch{throw Error('The server returned an unreadable response.')}if(!response.ok){if(response.status===401&&path!=='/api/login'){state.authenticated=false;renderLogin()}throw Error(data.error||`Request failed (${response.status})`)}return data}
function modal(title,body,wide=false){const dialog=$('#dialog');dialog.style.maxWidth=wide?'780px':'570px';dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2>${actionIcon('Close dialog','close-dialog','close')}</div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.querySelector('input:not([type=hidden]),select,textarea,button')?.focus()}
function closeDialog(){$('#dialog').close()}
function formError(form,error){let el=$('.form-error',form);if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');form.append(el)}el.textContent=error.message||String(error)}
function statusPill(){return `<span class="status-pill ${state.status?.online?'good':''}"><span class="dot ${state.status?.online?'online':'offline'}"></span>${state.status===null?'Checking':state.status.online?'Ollama connected':'Ollama offline'}</span>`}
function header(title,description,action='',eyebrow='DGX SPARK / OLLAMA'){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action}</div>`}
function offlineAlert(){return state.status&&!state.status.online?`<div class="alert">${icon('info')}<p><strong>Ollama is unavailable.</strong> ${esc(state.status.error||'Check the active server and its Ollama service.')} Saved jobs and settings are still available.</p></div>`:''}
function renderLogin(error=''){document.title=state.branding.title;$('#app').innerHTML=`<div class="login"><div class="login-card"><div class="login-brand"><span class="brand-mark">S<span>↗</span></span><div class="brand-copy">${esc(state.branding.title)}<small>DGX Spark control room</small></div></div><div class="eyebrow">PRIVATE ACCESS</div><h1>Your models. Your machine.</h1><p>Sign in to manage Ollama on your DGX Spark.</p><form id="login-form"><div class="form-group"><label for="password">Manager password</label><input class="field" id="password" name="password" type="password" required autocomplete="current-password" placeholder="Enter your password"></div>${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}<button class="btn primary" type="submit">Unlock control room ${icon('arrow')}</button></form><div class="login-foot">${icon('shield')}Protected access · models stay on your server</div><div class="login-attribution">Developed by Solomon</div></div></div>`}
function shell(reset=false){reset=reset||state.resetRender;state.resetRender=false;const oldMain=$('#main');const samePage=oldMain?.dataset.view===state.page;const saved=[];if(!reset){if($('#chat-input'))state.chatDraft=$('#chat-input').value;if(samePage)oldMain.querySelectorAll('input[id],textarea[id],select[id]').forEach(el=>{if(el.type!=='file')saved.push({id:el.id,value:el.value,checked:el.checked})})}const count=activeJobs().length;$('#app').innerHTML=`<aside class="sidebar" aria-label="Main navigation"><div class="brand"><span class="brand-mark">S<span>↗</span></span><div class="brand-copy">Spark<span class="lime">.</span><small>Ollama Manager</small></div></div><div class="nav-label">Workspace</div><nav>${pages.slice(0,6).map(p=>navItem(p,count)).join('')}</nav><div class="nav-label">System</div><nav>${pages.slice(6).map(p=>navItem(p,count)).join('')}</nav><div class="sidebar-foot"><div class="host-label"><span class="dot ${state.status?.online?'online':'offline'}"></span><span class="truncate">${esc(server()?.name||'DGX Spark')}</span></div><p>${esc(state.status?.system?.arch||'ARM64 ready')} · private workspace</p><p class="attribution">Developed by Solomon</p></div></aside><div class="layout ${state.page}"><header class="topbar"><div class="breadcrumb">Workspace ${icon('arrow')} <strong>${esc(labels[state.page])}</strong></div><div class="mobile-title"><span class="brand-mark">S<span>↗</span></span>Spark Manager</div><div class="top-actions">${statusPill()}<select id="active-server" class="server-select" aria-label="Active Ollama server" ${state.streaming?'disabled':''}>${(state.data?.servers||[]).map(s=>`<option value="${esc(s.id)}"${s.id===sid()?' selected':''}>${esc(s.name)}</option>`).join('')}</select>${actionIcon('Refresh server status','refresh','refresh')}<span class="avatar" aria-label="Private workspace">SG</span></div></header><main class="main" id="main" data-view="${state.page}" tabindex="-1">${pageContent()}<footer class="app-footer"><span>Developed by Solomon</span><span class="muted">Spark Ollama Manager · v1.1.0</span></footer></main><nav class="mobile-nav" aria-label="Mobile navigation">${['overview','models','chat','downloads'].map(p=>`<button type="button" data-page="${p}" class="${state.page===p?'active':''}"${state.page===p?' aria-current="page"':''}>${icon(p)}<span>${esc(p==='overview'?'Home':labels[p])}</span></button>`).join('')}<button type="button" data-action="more" class="${['discover','studio','benchmark','mcp','settings'].includes(state.page)?'active':''}" aria-label="More pages">${icon('more')}<span>More</span></button></nav></div>`;document.title=`${labels[state.page]} · ${state.branding.title}`;for(const item of saved){const el=document.getElementById(item.id);if(el){el.value=item.value;if(el.type==='checkbox')el.checked=item.checked}}afterRender()}
function navItem(p,count){return `<button type="button" class="nav-button ${state.page===p?'active':''}" data-page="${p}"${state.page===p?' aria-current="page"':''}>${icon(p)}${esc(labels[p])}${p==='downloads'&&count?`<span class="count">${count}</span>`:''}</button>`}
function render(){if(!state.authenticated)return renderLogin();if(!state.data)return $('#app').innerHTML='<div class="boot"><span class="spinner"></span><p>Loading your workspace…</p></div>';shell()}
function pageContent(){return `<section>${({overview:overview,models:modelsPage,discover:discover,downloads:downloads,studio:studio,chat:chat,benchmark:benchmark,mcp:mcpPage,settings:settings}[state.page])()}</section>`}
function metric(name,value,note,ico){return `<div class="metric"><div class="metric-top">${esc(name)}${icon(ico)}</div><div class="metric-value">${value}</div><div class="metric-note">${esc(note)}</div></div>`}
function overview(){const sys=state.status?.system;const total=Number(sys?.totalMemory);const free=Number(sys?.freeMemory);const used=Number.isFinite(total)&&Number.isFinite(free)?total-free:null;const percent=total&&used!==null?Math.round(used/total*100):null;const running=state.status?.running||[];const diskTotal=models().reduce((sum,m)=>sum+(Number(m.size)||0),0);const gpu=sys?.gpus||[];return `${header(state.branding.title,state.branding.subtitle,btn('Download model','pull-dialog','plus','primary'))}${offlineAlert()}<div class="metrics">${metric('Local models',state.status?.online?models().length:'—',state.status?.online?`${bytes(diskTotal)} of model files`:'Waiting for Ollama','models')}${metric('Loaded models',state.status?.online?running.length:'—','Currently held in memory','bolt')}${metric('System memory',used===null?'—':`${bytes(used).replace(' GB','')} <small>/ ${bytes(total)}</small>`,percent===null?'Host telemetry unavailable':`${percent}% in use · unified system memory`,'memory')}${metric('Active jobs',activeJobs().length,activeJobs().length?'Jobs continue when you close this tab':'Your queue is clear','downloads')}</div><div class="overview-grid"><div class="stack"><div class="panel"><div class="panel-head"><h2>Loaded models</h2><span class="hint">${running.length} in memory</span></div>${running.length?`<div class="table-wrap"><table class="models-table"><thead><tr><th>Model</th><th>Memory</th><th>Processor</th><th></th></tr></thead><tbody>${running.map(m=>`<tr><td><button class="model-name" data-action="show-model" data-model="${esc(modelName(m))}">${esc(modelName(m))}</button><div class="model-family">${esc(m.details?.parameter_size||'')} ${esc(m.details?.quantization_level||'')}</div></td><td data-label="Memory">${bytes(m.size)}</td><td data-label="Processor">${Number(m.size_vram)>0?`${Math.round(Number(m.size_vram)/Math.max(Number(m.size),1)*100)}% GPU`:'CPU / shared memory'}</td><td><div class="row-actions">${actionIcon('Unload '+modelName(m),'unload','stop',`data-model="${esc(modelName(m))}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No models loaded',state.status?.online?'Start a chat or a benchmark to load a model into memory.':'Connect to Ollama to see loaded models.',btn('Open chat','go-chat','chat'),'bolt')}</div><div class="panel"><div class="panel-head"><h2>System memory</h2><span class="hint">Live host telemetry</span></div><div class="panel-body"><div class="flex between"><strong>${used===null?'Unavailable':bytes(used)+' in use'}</strong><span class="muted small">${total?bytes(total)+' total':'—'}</span></div><div class="memory-track" role="meter" aria-label="System memory in use" aria-valuemin="0" aria-valuemax="100" ${percent!==null?`aria-valuenow="${percent}"`:''}><span class="memory-fill" style="width:${percent||0}%"></span></div><div class="memory-legend"><span><span class="dot online"></span> Used <strong>${bytes(used)}</strong></span><span>Available <strong>${bytes(sys?.freeMemory)}</strong></span><span>${percent===null?'No data':percent+'% utilized'}</span></div><div class="spec-list"><div><div class="spec-label">Host</div><div class="spec-value mono">${esc(sys?.hostname||'—')}</div></div><div><div class="spec-label">Platform</div><div class="spec-value">${esc(sys?.platform||'—')} · ${esc(sys?.arch||'—')}</div></div><div><div class="spec-label">Uptime</div><div class="spec-value">${elapsed(sys?.uptime)}</div></div><div><div class="spec-label">Load average</div><div class="spec-value mono">${Array.isArray(sys?.load)?sys.load.map(n=>Number(n).toFixed(2)).join(' / '):'—'}</div></div></div><p class="help">Host memory includes the operating system and every running service. Ollama GPU allocation is shown per loaded model when available.</p></div></div></div><div class="stack"><div class="panel"><div class="panel-head"><h2>Your machine</h2>${icon('cpu')}</div><div class="panel-body hardware-group">${gpu.length?gpu.map(g=>`<div class="hardware-card"><div class="hardware-icon">${icon('cpu')}</div><div><div class="hardware-title">${esc(g.name||'NVIDIA GPU')}</div><div class="hardware-note">${esc(g.memoryTotal?`${bytes(g.memoryUsed)} / ${bytes(g.memoryTotal)}`:(g.unifiedMemory?'Unified GPU memory':'Memory telemetry unavailable'))}${Number.isFinite(g.temperature)?` · ${esc(g.temperature)}°C`:''}</div></div></div>`).join(''):`<div class="hardware-card"><div class="hardware-icon">${icon('cpu')}</div><div><div class="hardware-title">GPU telemetry</div><div class="hardware-note">${state.status===null?'Checking host…':'Not reported by this host'}</div></div></div>`}<div class="hardware-card"><div class="hardware-icon">${icon('models')}</div><div><div class="hardware-title">Ollama ${esc(state.status?.version||'—')}</div><div class="hardware-note mono">${esc(server()?.url||'No server selected')}</div></div></div><div class="hardware-card"><div class="hardware-icon">${icon('shield')}</div><div><div class="hardware-title">Private control room</div><div class="hardware-note">Password protected · same origin API</div></div></div></div></div><div class="panel"><div class="panel-head"><h2>Recent activity</h2><button class="btn ghost small" data-page="downloads">View queue ${icon('arrow')}</button></div>${jobs().slice(0,3).length?jobs().slice(0,3).map(j=>`<div class="job-card"><div class="job-top">${icon(j.type==='benchmark'?'benchmark':'downloads')}<strong>${esc(j.model)}</strong><span class="tag job-status ${j.status==='completed'?'lime':''}">${esc(j.status)}</span></div><div class="job-meta">${esc(j.type)} · ${date(j.createdAt)}</div></div>`).join(''):empty('Nothing in the queue yet','Download a model, create a variant, or benchmark your Spark.','','clock')}</div></div></div><div class="footer-note">${icon('shield')} Model operations and inference are handled by the selected Ollama service.</div>`}
function modelsPage(){const list=models().filter(m=>modelName(m).toLowerCase().includes(state.modelSearch.toLowerCase())).sort((a,b)=>state.modelSort==='size'?(Number(b.size)||0)-(Number(a.size)||0):state.modelSort==='modified'?String(b.modified_at).localeCompare(String(a.modified_at)):modelName(a).localeCompare(modelName(b)));return `${header('Your model library','Inspect, copy, unload, and remove models on the selected server.',btn('Download model','pull-dialog','plus','primary'))}${offlineAlert()}<div class="toolbar"><div class="search">${icon('search')}<input id="model-search" class="field" type="search" value="${esc(state.modelSearch)}" aria-label="Search local models" placeholder="Search your models…"></div><select class="field" id="model-sort" aria-label="Sort models" style="width:165px"><option value="name"${state.modelSort==='name'?' selected':''}>Name A–Z</option><option value="size"${state.modelSort==='size'?' selected':''}>Largest first</option><option value="modified"${state.modelSort==='modified'?' selected':''}>Recently updated</option></select></div><div class="panel"><div class="panel-head"><h2>Local models <span class="muted small">(${models().length})</span></h2><span class="hint">${bytes(models().reduce((sum,m)=>sum+(Number(m.size)||0),0))} on disk</span></div>${list.length?`<div class="table-wrap"><table class="models-table"><thead><tr><th>Name</th><th>Parameters</th><th>Quantization</th><th>Size</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${list.map(m=>`<tr><td><button class="model-name" type="button" data-action="show-model" data-model="${esc(modelName(m))}">${esc(modelName(m))}</button><div class="model-family">${esc(m.details?.family||m.details?.format||'Local model')}</div></td><td data-label="Parameters">${esc(m.details?.parameter_size||'—')}</td><td data-label="Quantization"><span class="tag">${esc(m.details?.quantization_level||'—')}</span></td><td data-label="Size">${bytes(m.size)}</td><td data-label="Updated">${date(m.modified_at)}</td><td><div class="row-actions">${actionIcon('Inspect '+modelName(m),'show-model','info',`data-model="${esc(modelName(m))}"`)}${actionIcon('Chat with '+modelName(m),'chat-model','chat',`data-model="${esc(modelName(m))}"`)}${actionIcon('Copy '+modelName(m),'copy-model','copy',`data-model="${esc(modelName(m))}"`)}${actionIcon('Unload '+modelName(m),'unload','stop',`data-model="${esc(modelName(m))}"`)}${actionIcon('Delete '+modelName(m),'delete-model','trash',`data-model="${esc(modelName(m))}"`,true)}</div></td></tr>`).join('')}</tbody></table></div>`:empty(state.modelSearch?'No matching models':'Your library is ready for its first model',state.modelSearch?'Try a different model name.':'Download any Ollama model or import a GGUF file from your Spark.',state.modelSearch?'':btn('Download a model','pull-dialog','downloads','primary'))}</div>`}
function discover(){return `${header('Discover a model','Find your next model in the official library, then bring it to your Spark.',`<a class="btn" href="https://ollama.com/library" target="_blank" rel="noopener noreferrer">${icon('external')}Ollama library</a>`)}<div class="two-col"><div class="stack"><div class="panel"><div class="panel-head"><h2>Download by model reference</h2>${icon('downloads')}</div><div class="panel-body"><form id="pull-form"><div class="form-group"><label for="pull-model">Model name and tag</label><input id="pull-model" name="model" class="field mono" placeholder="model-name:tag" required maxlength="300"><p class="help">Copy the exact model reference from the Ollama library. A supported Hugging Face GGUF reference can use <span class="mono">hf.co/owner/repository:tag</span>.</p></div><div class="form-footer"><button class="btn primary" type="submit">${icon('downloads')}Start download</button></div></form></div></div><div class="panel"><div class="panel-head"><h2>Choosing a model</h2></div><div class="panel-body"><div class="studio-tip">${icon('memory')}<div><strong>Start with the workload</strong><p>Choose an instruct model for chat, a code model for development, or a vision model when you need image input.</p></div></div><div class="studio-tip">${icon('models')}<div><strong>Check the exact tag</strong><p>Parameter size, quantization, context length, and model license vary by release. Inspect the upstream model card before downloading.</p></div></div><div class="studio-tip">${icon('benchmark')}<div><strong>Measure on your Spark</strong><p>Use the benchmark page after downloading to compare speed and the response to your own prompt.</p></div></div></div></div></div><div class="panel"><div class="panel-head"><h2>Saved model references</h2>${btn('Add','bookmark-dialog','plus','small')}</div><div class="panel-body">${state.bookmarks.length?`<div class="bookmark-list">${state.bookmarks.map((b,i)=>`<div class="bookmark-row"><div><strong>${esc(b.model)}</strong><small>${esc(b.note||'Saved in this browser')}</small></div><div class="flex">${actionIcon('Download '+b.model,'pull-bookmark','downloads',`data-index="${i}"`)}${actionIcon('Edit '+b.model,'edit-bookmark','edit',`data-index="${i}"`)}${actionIcon('Remove bookmark','remove-bookmark','trash',`data-index="${i}"`,true)}</div></div>`).join('')}</div><p class="help">References are saved on this browser, independently of your models.</p>`:empty('Keep a shortlist','Save model references here so you can download them later.','','book')}</div></div></div>`}
function renderJob(j){const progress=Number(j.total)>0?Math.min(100,Math.max(0,Number(j.completed||0)/Number(j.total)*100)):null;const live=['queued','running'].includes(j.status);const result=j.result;return `<div class="job-card"><div class="job-top">${icon(j.type==='benchmark'?'benchmark':'downloads')}<strong>${esc(j.model)}</strong><span class="tag job-status ${j.status==='completed'?'lime':''}">${esc(j.status)}</span></div><div class="job-meta">${esc(j.type)} · ${date(j.createdAt)} · ${esc(state.data.servers.find(s=>s.id===j.serverId)?.name||j.serverId)}</div>${live?`<div class="progress-track" role="progressbar" aria-label="${esc(j.model)} job progress"${progress!==null?` aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(progress)}"`:''}><span class="${progress===null?'progress-indeterminate':''}" style="width:${progress||0}%"></span></div>`:''}<div class="job-bottom" style="margin-top:12px"><p class="${j.error?'danger-text':''}">${esc(j.error||j.message||'Waiting for worker')}${progress!==null?` · ${bytes(j.completed)} / ${bytes(j.total)} (${Math.round(progress)}%)`:''}</p><div class="flex">${live?btn('Cancel','cancel-job','stop','small',`data-id="${esc(j.id)}"`):['failed','cancelled','interrupted'].includes(j.status)?btn('Retry','retry-job','refresh','small',`data-id="${esc(j.id)}"`):''}${result?btn('Result','job-result','info','small',`data-id="${esc(j.id)}"`):''}</div></div>${j.type==='benchmark'&&j.status==='completed'&&result?benchmarkMetrics(result):''}</div>`}
function downloads(){const list=jobs().filter(j=>j.type!=='benchmark');return `${header('Download queue','Persistent jobs keep running when you close this tab.',btn('New download','pull-dialog','plus','primary'))}<div class="alert info">${icon('info')}<p>Cancelling stops the request. Ollama keeps partial model files so a later download can reuse them.</p></div><div class="panel"><div class="panel-head"><h2>Model jobs</h2><span class="hint">${list.filter(j=>['running','queued'].includes(j.status)).length} active · ${list.length} total</span></div>${list.length?list.map(renderJob).join(''):empty('No downloads yet','Download a model or create a variant to see its progress here.',btn('Find a model','go-discover','discover'),'downloads')}</div>`}
function studio(){return `${header('Model Studio','Build a focused model variant or import a local GGUF.')}<div class="tabs" role="tablist" aria-label="Model Studio mode"><button type="button" role="tab" aria-selected="${state.studioTab==='create'}" class="tab ${state.studioTab==='create'?'active':''}" data-action="studio-create">Create a variant</button><button type="button" role="tab" aria-selected="${state.studioTab==='import'}" class="tab ${state.studioTab==='import'?'active':''}" data-action="studio-import">Import GGUF</button></div><div class="two-col"><div class="panel"><div class="panel-head"><h2>${state.studioTab==='create'?'Customize a local model':'Import from the Spark'}</h2>${icon('studio')}</div><div class="panel-body">${state.studioTab==='create'?`<form id="create-form"><div class="form-group"><label for="create-name">New model name</label><input class="field mono" id="create-name" name="model" placeholder="my-assistant:latest" required maxlength="300"></div><div class="form-group"><label for="create-from">Base model</label><select class="field" id="create-from" name="from" required>${modelOptions()}</select></div><div class="form-group"><label for="create-system">System prompt</label><textarea class="field" id="create-system" name="system" placeholder="Define this assistant’s purpose, tone, and instructions…" maxlength="30000"></textarea></div><div class="form-group"><label for="create-params">Parameters (JSON)</label><textarea class="field mono" id="create-params" name="parameters" rows="3" placeholder='{"temperature":0.7,"num_ctx":4096}'></textarea><p class="help">Use Ollama parameter names. Leave empty to keep the base defaults.</p></div><div class="form-group"><label for="create-template">Prompt template (optional)</label><textarea class="field mono" id="create-template" name="template" rows="3" placeholder="Ollama Go template"></textarea></div><div class="form-group"><label for="create-quantize">Quantization (optional)</label><select class="field" id="create-quantize" name="quantize"><option value="">Keep existing quantization</option><option value="q4_K_M">Q4_K_M</option><option value="q4_K_S">Q4_K_S</option><option value="q5_K_M">Q5_K_M</option><option value="q5_K_S">Q5_K_S</option><option value="q8_0">Q8_0</option></select><p class="help">Quantization requires a compatible full precision source model.</p></div><div class="form-footer"><button class="btn primary" type="submit">${icon('studio')}Create model</button></div></form>`:`<form id="import-form"><div class="form-group"><label for="import-model">Model name</label><input class="field mono" id="import-model" name="model" placeholder="my-import:latest" required maxlength="300"></div><div class="form-group"><label for="import-path">GGUF file on this server</label><select class="field" id="import-path" name="path" required><option value="">Loading configured import folder…</option></select><p class="help" id="import-roots">The server only exposes GGUF files inside its configured import folder. Files are uploaded to Ollama; source files stay in place.</p></div><div class="form-group"><label for="import-system">System prompt (optional)</label><textarea class="field" id="import-system" name="system"></textarea></div><div class="form-footer">${btn('Rescan','rescan-import','refresh')}<button class="btn primary" type="submit">${icon('downloads')}Import model</button></div></form>`}</div></div><div class="stack"><div class="panel"><div class="panel-head"><h2>A model that fits your work</h2></div><div class="panel-body"><div class="studio-tip">${icon('models')}<div><strong>Reuse your local library</strong><p>Create starts from a model installed on the active Ollama server. Your base model stays available.</p></div></div><div class="studio-tip">${icon('chat')}<div><strong>Make the instructions specific</strong><p>Describe the assistant’s role, output format, and boundaries. Test the new model in Chat when its job completes.</p></div></div><div class="studio-tip">${icon('shield')}<div><strong>Review model licenses</strong><p>Imported and derived models retain their upstream license requirements.</p></div></div></div></div><div class="alert info">${icon('clock')}<p>Creation and imports use the persistent queue. Track progress on the Downloads page.</p></div></div></div>`}
function chat(){if(!state.chatModel&&models().length)state.chatModel=modelName(models()[0]);return `${header('Chat workspace','Talk to your local models. Conversations are saved on your manager.',btn('New chat','new-chat','plus','primary'))}${offlineAlert()}<div class="panel chat-grid"><aside class="chat-history" aria-label="Conversation history">${btn('New conversation','new-chat','plus')}<div class="history-label">Saved conversations</div>${(state.data.chats||[]).filter(c=>c.serverId===sid()).length?(state.data.chats||[]).filter(c=>c.serverId===sid()).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).map(c=>`<div class="history-item ${c.id===state.chatId?'active':''}"><button type="button" data-action="open-chat" data-id="${esc(c.id)}"><span class="truncate" style="display:block">${esc(c.title||'Untitled conversation')}</span><small>${esc(c.model)} · ${date(c.updatedAt)}</small></button>${actionIcon('Delete conversation','delete-chat','trash',`data-id="${esc(c.id)}"`,true)}</div>`).join(''):'<p class="help">Your conversations appear here after your first message.</p>'}</aside><div class="chat-main"><div class="chat-tools"><select class="field mono" id="chat-model" aria-label="Chat model" ${state.streaming||state.chatId?'disabled':''}>${modelOptions(state.chatModel)}</select><div class="flex">${actionIcon('Saved conversations','chat-history','clock')}${actionIcon('Chat options and assistant presets','chat-options','settings')}${actionIcon('Export conversation','export-chat','downloads')}</div></div>${chatMcpBar()}<div class="chat-messages" id="chat-messages" aria-live="off">${renderMessages()}</div><form id="chat-form" class="chat-compose"><div id="attachments" class="attachment-list">${renderAttachments()}</div><div class="compose-box"><button class="icon-btn" type="button" data-action="attach-file" title="Attach image or text file" aria-label="Attach image or text file">${icon('attach')}</button><input id="chat-file" type="file" accept="image/png,image/jpeg,image/webp,.txt,.md,.js,.ts,.py,.json,.html,.css,.sh,.java,.c,.cpp,.go,.rs" multiple hidden><textarea id="chat-input" name="message" rows="2" placeholder="Message your local model…" aria-label="Message" ${state.streaming?'disabled':''}>${esc(state.chatDraft)}</textarea>${state.streaming?btn('','stop-chat','stop','danger'): `<button class="btn primary" type="submit" aria-label="Send message" ${!state.chatModel?'disabled':''}>${icon('send')}</button>`}</div><div class="compose-help"><span>Enter to send · Shift + Enter for a new line</span><span>${state.streaming?'Generating on your server…':'Your selected Ollama service'}</span></div></form></div></div>`}
function renderMessages(){if(!state.messages.length)return `<div class="chat-welcome"><span class="brand-mark">S<span>↗</span></span><h2>What will you build today?</h2><p>Select a model and start a conversation. Your prompts and responses stay on your manager.</p>${!models().length?btn('Download your first model','pull-dialog','downloads','primary'):''}</div>`;return state.messages.filter(m=>m.role==='user'||m.role==='assistant').map((m,i)=>`<article class="message ${m.role==='user'?'user':'assistant'}"><div class="message-label"><span>${m.role==='user'?'You':esc(state.chatModel||'Assistant')}</span>${m.content?actionIcon('Copy message','copy-message','copy',`data-index="${i}"`):''}</div>${m.thinking?`<details class="thinking"><summary>Reasoning</summary><div>${esc(m.thinking)}</div></details>`:''}<pre class="message-body">${esc(m.content||'')}${!m.content&&state.streaming&&m===state.messages[state.messages.length-1]?'<span class="spinner" aria-label="Generating"></span>':''}</pre></article>`).join('')+renderToolEvents()}
function renderAttachments(){return state.attachments.map((a,i)=>`<span class="attachment">${icon('attach')}${esc(a.name)}<button type="button" aria-label="Remove ${esc(a.name)}" data-action="remove-attachment" data-index="${i}">×</button></span>`).join('')}
function benchmarkMetrics(result){const tokens=Number(result.eval_count||result.evalCount||result.tokens||0);const duration=Number(result.eval_duration||result.evalDuration||0)/1e9;const tps=Number(result.tokens_per_second||result.tokensPerSecond||(duration?tokens/duration:0));return `<div class="bench-results"><div class="bench-result"><span>Generation speed</span><strong>${Number.isFinite(tps)?tps.toFixed(1):'—'}</strong><span>tokens / second</span></div><div class="bench-result"><span>Generated tokens</span><strong>${tokens||'—'}</strong><span>response length</span></div><div class="bench-result"><span>Generation time</span><strong>${duration?duration.toFixed(2):'—'}</strong><span>seconds</span></div></div>`}
function benchmark(){const list=jobs('benchmark');return `${header('Benchmark your Spark','Measure local generation speed with the same prompt across models.')}<div class="two-col"><div class="stack"><div class="panel"><div class="panel-head"><h2>Run a benchmark</h2>${icon('benchmark')}</div><div class="panel-body"><form id="benchmark-form"><div class="form-group"><label for="bench-model">Local model</label><select class="field mono" id="bench-model" name="model" required>${modelOptions()}</select></div><div class="form-group"><label for="bench-prompt">Benchmark prompt</label><textarea class="field" id="bench-prompt" name="prompt" required maxlength="30000" rows="5">Explain how a transformer language model generates its next token, using a clear step-by-step example.</textarea></div><p class="help">The response is generated by the active server. A first run may include model loading; repeat with the same prompt for a fair comparison.</p><div class="form-footer"><button class="btn primary" type="submit">${icon('play')}Run benchmark</button></div></form></div></div><div class="alert info">${icon('info')}<p>Generation speed uses Ollama’s token count and evaluation duration. It is a workload measurement, not a GPU utilization score.</p></div></div><div class="panel"><div class="panel-head"><h2>Benchmark results</h2><span class="hint" id="benchmark-count">${list.length} runs</span></div><div id="benchmark-jobs">${list.length?list.map(renderJob).join(''):empty('Your first measurement awaits','Choose a local model and a representative prompt to record a result.','','benchmark')}</div></div></div>`}
function settings(){return `${header('Workspace settings','Manage server connections, workspace content, and private access.')}<div class="settings-grid"><div class="stack"><div class="panel"><div class="panel-head"><h2>Workspace content</h2></div><div class="panel-body"><form id="settings-form"><div class="form-group"><label for="workspace-title">Workspace title</label><input class="field" id="workspace-title" name="title" value="${esc(state.branding.title)}" required maxlength="80"></div><div class="form-group"><label for="workspace-subtitle">Overview description</label><input class="field" id="workspace-subtitle" name="subtitle" value="${esc(state.branding.subtitle)}" maxlength="180"></div><div class="form-footer"><button class="btn primary" type="submit">${icon('check')}Save changes</button></div></form></div></div><div class="panel"><div class="panel-head"><h2>Ollama servers</h2>${btn('Add server','server-dialog','plus','small')}</div>${state.data.servers.map(s=>`<div class="server-row"><div><strong>${esc(s.name)} ${s.id===sid()?'<span class="tag lime">Active</span>':''}</strong><small>${esc(s.url)}</small></div><div class="flex">${s.id!==sid()?actionIcon('Select '+s.name,'select-server','check',`data-id="${esc(s.id)}"`):''}${actionIcon('Edit '+s.name,'edit-server','edit',`data-id="${esc(s.id)}"`)}${s.id!=='local'?actionIcon('Delete '+s.name,'delete-server','trash',`data-id="${esc(s.id)}"`,true):''}</div></div>`).join('')}<div class="panel-body"><p class="help">Use a private or loopback address accessible from the manager host. Your browser talks to the manager; the manager connects to Ollama.</p></div></div></div><div class="stack"><div class="panel"><div class="panel-head"><h2>Connection status</h2>${statusPill()}</div><div class="panel-body"><div class="spec-list"><div><div class="spec-label">Active server</div><div class="spec-value">${esc(server()?.name||'—')}</div></div><div><div class="spec-label">Ollama version</div><div class="spec-value mono">${esc(state.status?.version||'—')}</div></div><div><div class="spec-label">Manager host</div><div class="spec-value mono">${esc(state.status?.system?.hostname||'—')}</div></div><div><div class="spec-label">Architecture</div><div class="spec-value mono">${esc(state.status?.system?.arch||'—')}</div></div></div>${state.status?.error?`<p class="help danger-text">${esc(state.status.error)}</p>`:''}<div class="form-footer">${btn('Check connection','refresh','refresh')}</div></div></div><div class="install-card"><div><strong>Keep Spark within reach</strong><p>Add this workspace to your home screen for a native app feel. Requires HTTPS or localhost.</p></div>${btn('Install','install','downloads')}</div><div class="panel"><div class="panel-head"><h2>Session and privacy</h2>${icon('shield')}</div><div class="panel-body"><p class="help">Your conversations and jobs are stored on this manager. Model downloads and inference use the active Ollama server. Signing out clears this browser’s active session.</p><p class="help attribution">Developed by Solomon</p><div class="form-footer">${btn('Sign out','logout','logout','danger')}</div></div></div></div></div>`}
async function refresh(initial=false){if(state.pollBusy||!state.authenticated)return;state.pollBusy=true;try{const data=await api('/api/state');const previousServer=sid();if(previousServer&&previousServer!==data.activeServerId){state.chatId=null;state.chatModel='';state.chatDraft='';state.messages=[];state.toolEvents=[];state.mcpSelected=[];state.attachments=[];state.resetRender=true;initial=true;closeDialog();toast('The active server changed in another session.')}state.data=data;state.branding={...state.branding,...data.settings};const status=await api(`/api/status?serverId=${encodeURIComponent(data.activeServerId)}`);state.status=status;if(!initial&&state.page==='benchmark'){updateBenchmarkJobs()}if(initial||['overview','models','downloads'].includes(state.page)){if(!$('#dialog').open&&!state.streaming){const focus=document.activeElement;const id=focus?.id;const start=focus?.selectionStart;shell();if(id){const el=document.getElementById(id);el?.focus();if(start!==null&&start!==undefined&&el?.setSelectionRange){try{el.setSelectionRange(start,start)}catch{}}}}}}catch(error){if(initial){$('#app').innerHTML=`<div class="offline-shell">${icon('info')}<h1>Unable to load the workspace</h1><p>${esc(error.message)}</p>${btn('Try again','reload','refresh','primary')}</div>`}else if(!navigator.onLine)toast('You are offline. Reconnect to manage your Spark.',true)}finally{state.pollBusy=false}}
async function refreshData(){state.data=await api('/api/state');state.branding={...state.branding,...state.data.settings}}
async function navigate(page,reset=false){if(!pages.includes(page))return;if(state.streaming&&page!=='chat')return toast('Stop or finish the current response before changing pages.');state.page=page;location.hash=page;shell(reset);window.scrollTo({top:0,behavior:'instant'})}
async function afterRender(){if(state.page==='studio'&&state.studioTab==='import')await loadImportFiles();if(state.page==='chat')scrollChat()}
function updateBenchmarkJobs(){const list=jobs('benchmark');if($('#benchmark-jobs'))$('#benchmark-jobs').innerHTML=list.length?list.map(renderJob).join(''):empty('Your first measurement awaits','Choose a local model and a representative prompt to record a result.','','benchmark');if($('#benchmark-count'))$('#benchmark-count').textContent=`${list.length} runs`}
function scrollChat(){const area=$('#chat-messages');if(area)area.scrollTop=area.scrollHeight}
async function loadImportFiles(){const select=$('#import-path');const roots=$('#import-roots');if(!select||!roots)return;try{const data=await api('/api/import-files');if(!select.isConnected)return;select.innerHTML=data.files.length?'<option value="">Select a GGUF file</option>'+data.files.map(f=>`<option value="${esc(f.path)}">${esc(f.name)} · ${bytes(f.size)}</option>`).join(''):'<option value="">No GGUF files in the import folder</option>';roots.textContent=`Import folders: ${data.roots.join(', ')||'Not configured'}. Place your GGUF file here, then rescan. Source files stay in place.`}catch(error){if(!select.isConnected)return;select.innerHTML='<option value="">Import files unavailable</option>';roots.textContent=error.message}}
async function startJob(input){const job=await api('/api/jobs',{serverId:sid(),...input});await refreshData();closeDialog();toast(`${input.type==='benchmark'?'Benchmark':'Model job'} queued.`);await navigate(input.type==='benchmark'?'benchmark':'downloads');return job}
function pullDialog(model=''){modal('Download a model',`<form id="pull-form"><div class="form-group"><label for="pull-model">Model name and tag</label><input id="pull-model" name="model" class="field mono" value="${esc(model)}" placeholder="model-name:tag" required maxlength="300"><p class="help">Use the exact reference from the Ollama library.</p></div><div class="form-footer">${btn('Cancel','close-dialog')}<button type="submit" class="btn primary">${icon('downloads')}Start download</button></div></form>`)}
function confirmDialog(title,text,action,data,confirm='Confirm',danger=true){modal(title,`<p class="muted small">${esc(text)}</p><div class="form-footer">${btn('Cancel','close-dialog')}${btn(confirm,action,danger?'trash':'check',danger?'danger':'primary',data)}</div>`)}
function serverDialog(existing){modal(existing?'Edit server':'Add Ollama server',`<form id="server-form">${existing?`<input type="hidden" name="id" value="${esc(existing.id)}">`:''}<div class="form-group"><label for="server-name">Display name</label><input class="field" id="server-name" name="name" value="${esc(existing?.name||'')}" required maxlength="80" placeholder="DGX Spark"></div><div class="form-group"><label for="server-url">Private Ollama URL</label><input class="field mono" id="server-url" name="url" value="${esc(existing?.url||'http://127.0.0.1:11434')}" type="url" required placeholder="http://127.0.0.1:11434"><p class="help">Address must be reachable from the manager host. Public destinations are rejected.</p></div><div class="form-footer">${btn('Cancel','close-dialog')}<button class="btn primary" type="submit">Save server</button></div></form>`)}
function bookmarkDialog(index){const item=state.bookmarks[index];modal(item?'Edit model reference':'Save model reference',`<form id="bookmark-form"><input name="index" type="hidden" value="${index??''}"><div class="form-group"><label for="bookmark-model">Model reference</label><input class="field mono" id="bookmark-model" name="model" value="${esc(item?.model||'')}" required maxlength="300"></div><div class="form-group"><label for="bookmark-note">Note (optional)</label><input class="field" id="bookmark-note" name="note" value="${esc(item?.note||'')}" maxlength="150"></div><p class="help">Saved on this browser. No catalog information is inferred.</p><div class="form-footer">${btn('Cancel','close-dialog')}<button class="btn primary" type="submit">Save reference</button></div></form>`)}
function chatOptions(){modal('Chat options and assistant presets',`<form id="chat-options-form"><div class="form-group"><label for="preset-select">Assistant preset</label><select class="field" id="preset-select" ${state.chatId?'disabled':''}><option value="">Custom instructions</option>${state.presets.map((p,i)=>`<option value="${i}">${esc(p.name)}</option>`).join('')}</select></div><div class="form-group"><label for="chat-system">System prompt</label><textarea class="field" id="chat-system" name="system" rows="5" maxlength="30000" ${state.chatId?'readonly':''}>${esc(state.systemPrompt)}</textarea><p class="help">Applied to new conversations. Start a new chat to change the instructions of a saved conversation.</p></div><div class="form-grid"><div class="form-group"><label for="temperature">Temperature</label><input class="field" id="temperature" name="temperature" type="number" min="0" max="2" step="0.05" value="${state.chatOptions.temperature}"></div><div class="form-group"><label for="context-size">Context tokens</label><input class="field" id="context-size" name="num_ctx" type="number" min="256" max="262144" step="256" value="${state.chatOptions.num_ctx}"></div></div><div class="form-group"><label for="preset-name">Save as a preset (optional)</label><input class="field" id="preset-name" name="presetName" maxlength="80" placeholder="e.g. Code reviewer"><p class="help">Preset instructions are saved on this browser. Matching names replace the existing preset.</p></div>${state.presets.length?`<div class="flex wrap">${state.presets.map((p,i)=>`<span class="attachment">${esc(p.name)}<button type="button" aria-label="Delete ${esc(p.name)} preset" data-action="delete-preset" data-index="${i}">×</button></span>`).join('')}</div>`:''}<div class="form-footer">${btn('Cancel','close-dialog')}<button class="btn primary" type="submit">Save options</button></div></form>`)}
async function selectServer(id){if(state.streaming)return toast('Stop the current response before switching servers.',true);await api('/api/active-server',{id});state.status=null;state.chatId=null;state.messages=[];state.chatModel='';state.chatDraft='';state.toolEvents=[];state.mcpSelected=[];state.attachments=[];state.resetRender=true;await refresh(true);toast('Active server changed.')}
function exportChat(){if(!state.messages.length)return toast('There are no messages to export yet.');const text=`# ${state.chatModel} conversation\n\n`+state.messages.filter(m=>m.role!=='system').map(m=>`## ${m.role==='user'?'You':'Assistant'}\n\n${m.thinking?`Reasoning:\n${m.thinking}\n\n`:''}${m.content||''}`).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`spark-chat-${new Date().toISOString().slice(0,10)}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{modal('Copy text',`<textarea class="field" rows="8" readonly>${esc(text)}</textarea><p class="help">Select the text and copy it with your device’s copy command.</p>`)}}
async function attachFiles(files){for(const file of files){if(state.attachments.length>=4){toast('Attach up to four files per message.',true);break}if(file.size>6*1024*1024){toast(`${file.name} exceeds 6 MB.`,true);continue}if(/^image\/(png|jpeg|webp)$/.test(file.type)){const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Unable to read image.'));reader.readAsDataURL(file)});state.attachments.push({name:file.name,type:'image',data})}else if(/\.(txt|md|js|ts|py|json|html|css|sh|java|c|cpp|go|rs)$/i.test(file.name)){if(file.size>64000){toast(`${file.name} text attachment exceeds 64 KB.`,true);continue}state.attachments.push({name:file.name,type:'text',data:await file.text()})}else toast(`Unsupported attachment: ${file.name}`,true)}if($('#attachments'))$('#attachments').innerHTML=renderAttachments()}
async function sendChat(form){const field=$('#chat-input');let content=field.value.trim();if(!content&&!state.attachments.length)return;if(!state.chatModel)return toast('Select a local model first.',true);if(state.streaming)return;const previousMessages=state.messages.slice();const originalDraft=content;const originalAttachments=state.attachments.slice();let failed=false;const images=state.attachments.filter(a=>a.type==='image').map(a=>a.data);const textAttachments=state.attachments.filter(a=>a.type==='text');if(textAttachments.length)content+='\n\n'+textAttachments.map(a=>`Attached file: ${a.name}\n${a.data}`).join('\n\n');if(images.length)content=content||'Describe the attached image.';if(content.length>65536)return toast('The message and text attachments exceed 65,536 characters. Shorten the message or remove a file.',true);state.messages.push({role:'user',content});state.messages.push({role:'assistant',content:'',thinking:''});const assistant=state.messages[state.messages.length-1];state.attachments=[];state.chatDraft='';field.value='';state.streaming=true;state.chatController=new AbortController();shell();try{const response=await fetch('/api/chat',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({chatId:state.chatId||undefined,serverId:sid(),model:state.chatModel,message:content,images:images.length?images:undefined,system:state.systemPrompt||undefined,options:state.chatOptions,mcpServerIds:state.mcpSelected.filter(id=>mcpServers().some(s=>s.id===id&&s.enabled))}),signal:state.chatController.signal});if(!response.ok){const data=await response.json();throw Error(data.error||'Unable to start chat.')}const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';const chunk=line=>{if(!line.trim())return;const data=JSON.parse(line);if(data.error)throw Error(data.error);if(data.chatId)state.chatId=data.chatId;if(data.toolCall){recordToolEvent(data.toolCall);toast(`Review MCP tool request: ${data.toolCall.name||'tool call'}`)}if(data.toolResult)recordToolEvent(data.toolResult);if(data.message){assistant.content+=data.message.content||'';assistant.thinking+=data.message.thinking||''}if(data.eval_count)assistant.eval_count=data.eval_count;const area=$('#chat-messages');if(area){const nearBottom=area.scrollHeight-area.scrollTop-area.clientHeight<100;area.innerHTML=renderMessages();if(nearBottom)scrollChat()}};while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let pos;while((pos=buffer.indexOf('\n'))>=0){chunk(buffer.slice(0,pos));buffer=buffer.slice(pos+1)}}buffer+=decoder.decode();if(buffer.trim())chunk(buffer)}catch(error){if(error.name==='AbortError')toast('Generation stopped.');else{failed=true;toast(error.message,true);if(!assistant.content)assistant.content=`Generation failed: ${error.message}`}}finally{state.streaming=false;state.chatController=null;try{await refreshData();if(state.chatId){const saved=await api(`/api/chats/${encodeURIComponent(state.chatId)}`);state.messages=saved.messages;state.toolEvents=saved.toolEvents||state.toolEvents}}catch{}if(failed&&!state.chatId){state.messages=previousMessages;state.chatDraft=originalDraft;state.attachments=originalAttachments}shell(true);$('#chat-input')?.focus()}}
async function action(button){const a=button.dataset.action;const model=button.dataset.model;const id=button.dataset.id;const index=Number(button.dataset.index);switch(a){
 case 'mcp-add':mcpDialog();break;
 case 'mcp-edit':mcpDialog(mcpServers().find(s=>s.id===id));break;
 case 'mcp-toggle':await toggleMcp(id);break;
 case 'mcp-test':await testMcp(id,button);break;
 case 'mcp-tools':await showMcpTools(id,button);break;
 case 'mcp-delete':confirmDialog('Delete MCP connection?','Remove this saved connection from the manager. The external service is not deleted.','mcp-confirm-delete',`data-id="${esc(id)}"`,'Delete connection');break;
 case 'mcp-confirm-delete':await api(`/api/mcp/servers/${encodeURIComponent(id)}`,undefined,'DELETE');state.mcpSelected=state.mcpSelected.filter(value=>value!==id);await refreshData();closeDialog();shell();toast('MCP connection removed.');break;
 case 'mcp-select':if(state.streaming)return toast('Finish or stop generation before changing MCP connections.');mcpSelectionDialog();break;
 case 'tool-approve':await decideTool(id,true,button);break;
 case 'tool-deny':await decideTool(id,false,button);break;
 case 'close-dialog':closeDialog();break;
 case 'reload':await boot();break;
 case 'refresh':if(state.streaming)return toast('Finish or stop generation before refreshing.');button.disabled=true;await refresh(true);toast('Server status refreshed.');break;
 case 'pull-dialog':pullDialog();break;
 case 'go-chat':await navigate('chat');break;
 case 'go-discover':await navigate('discover');break;
 case 'more':modal('Your workspace',`<nav>${['discover','studio','benchmark','mcp','settings'].map(p=>`<button class="nav-button" type="button" data-page="${p}">${icon(p)}${esc(labels[p])}${icon('arrow')}</button>`).join('')}</nav>`);break;
 case 'show-model':modal(model,'<div class="loading-panel"><span class="spinner"></span>Inspecting model…</div>',true);try{const info=await api('/api/show',{serverId:sid(),model});modal(model,`<div class="spec-list"><div><div class="spec-label">Family</div><div class="spec-value">${esc(info.details?.family||'—')}</div></div><div><div class="spec-label">Parameters</div><div class="spec-value">${esc(info.details?.parameter_size||'—')}</div></div><div><div class="spec-label">Quantization</div><div class="spec-value mono">${esc(info.details?.quantization_level||'—')}</div></div><div><div class="spec-label">Capabilities</div><div class="spec-value">${esc((info.capabilities||[]).join(', ')||'Not reported')}</div></div></div>${info.system?`<h3>System prompt</h3><pre>${esc(info.system)}</pre>`:''}${info.parameters?`<h3>Parameters</h3><pre>${esc(typeof info.parameters==='string'?info.parameters:JSON.stringify(info.parameters,null,2))}</pre>`:''}${info.modelfile?`<details><summary class="small muted">Modelfile</summary><pre>${esc(info.modelfile)}</pre></details>`:''}${info.license?`<details><summary class="small muted">License</summary><pre>${esc(info.license)}</pre></details>`:''}<details><summary class="small muted">All model metadata</summary><pre>${esc(JSON.stringify(info,null,2))}</pre></details><div class="form-footer">${btn('Chat with model','chat-model','chat','primary',`data-model="${esc(model)}"`)}</div>`,true)}catch(error){modal(model,`<p class="form-error" role="alert">${esc(error.message)}</p>`)}break;
 case 'chat-model':if(state.streaming)break;closeDialog();state.chatModel=model;state.chatId=null;state.messages=[];state.toolEvents=[];state.mcpSelected=[];state.chatDraft='';state.attachments=[];await navigate('chat',true);break;
 case 'copy-model':modal('Copy model',`<form id="copy-form"><input type="hidden" name="source" value="${esc(model)}"><p class="help">Create another name for <span class="mono">${esc(model)}</span>.</p><div class="form-group" style="margin-top:18px"><label for="copy-destination">New model name</label><input class="field mono" id="copy-destination" name="destination" required maxlength="300" placeholder="my-model:latest"></div><div class="form-footer">${btn('Cancel','close-dialog')}<button class="btn primary" type="submit">Copy model</button></div></form>`);break;
 case 'delete-model':confirmDialog('Delete model?',`Remove ${model} from ${server()?.name}? Saved conversations remain available.`, 'confirm-delete-model',`data-model="${esc(model)}"`,'Delete model');break;
 case 'confirm-delete-model':button.disabled=true;await api('/api/delete',{serverId:sid(),model});closeDialog();await refresh(true);toast('Model deleted.');break;
 case 'unload':confirmDialog('Unload model?',`Release ${model} from memory on the active server. The model remains installed.`, 'confirm-unload',`data-model="${esc(model)}"`,'Unload',false);break;
 case 'confirm-unload':button.disabled=true;await api('/api/unload',{serverId:sid(),model});closeDialog();await refresh(true);toast('Model unloaded.');break;
 case 'cancel-job':confirmDialog('Cancel job?','Stop this job. Ollama keeps partial model downloads for reuse.','confirm-cancel-job',`data-id="${esc(id)}"`,'Cancel job');break;
 case 'confirm-cancel-job':button.disabled=true;await api(`/api/jobs/${encodeURIComponent(id)}/cancel`,{});closeDialog();await refresh(true);toast('Job cancellation requested.');break;
 case 'retry-job':button.disabled=true;await api(`/api/jobs/${encodeURIComponent(id)}/retry`,{});await refresh(true);toast('Retry queued.');break;
 case 'job-result':{const j=jobs().find(j=>j.id===id);modal('Job result',`${j?.type==='benchmark'?benchmarkMetrics(j.result):''}<pre>${esc(JSON.stringify(j?.result,null,2))}</pre>`,true);break}
 case 'studio-create':state.studioTab='create';shell();break;
 case 'studio-import':state.studioTab='import';shell();break;
 case 'rescan-import':await loadImportFiles();break;
 case 'bookmark-dialog':bookmarkDialog();break;
 case 'edit-bookmark':bookmarkDialog(index);break;
 case 'remove-bookmark':state.bookmarks.splice(index,1);saveLocal('spark-bookmarks',state.bookmarks);shell();break;
 case 'pull-bookmark':pullDialog(state.bookmarks[index].model);break;
 case 'server-dialog':serverDialog();break;
 case 'edit-server':serverDialog(state.data.servers.find(s=>s.id===id));break;
 case 'select-server':await selectServer(id);break;
 case 'delete-server':confirmDialog('Remove server?','Remove this saved connection. Models and Ollama on that server are not deleted.','confirm-delete-server',`data-id="${esc(id)}"`,'Remove server');break;
 case 'confirm-delete-server':await api(`/api/servers/${encodeURIComponent(id)}`,undefined,'DELETE');closeDialog();await refresh(true);toast('Server connection removed.');break;
 case 'new-chat':if(state.streaming)return toast('Stop the current response first.');state.chatId=null;state.messages=[];state.toolEvents=[];state.mcpSelected=[];state.attachments=[];state.chatDraft='';await navigate('chat',true);$('#chat-input')?.focus();break;
 case 'open-chat':if(state.streaming)return toast('Stop the current response first.');{const c=await api(`/api/chats/${encodeURIComponent(id)}`);state.chatId=c.id;state.chatModel=c.model;state.messages=c.messages;state.toolEvents=c.toolEvents||[];state.mcpSelected=[];state.systemPrompt=c.messages.find(m=>m.role==='system')?.content||'';state.chatDraft='';state.attachments=[];closeDialog();shell(true);break}
 case 'delete-chat':if(state.streaming)return toast('Stop the current response first.');confirmDialog('Delete conversation?','Permanently remove this saved conversation from the manager.','confirm-delete-chat',`data-id="${esc(id)}"`,'Delete conversation');break;
 case 'confirm-delete-chat':await api(`/api/chats/${encodeURIComponent(id)}`,undefined,'DELETE');if(state.chatId===id){state.chatId=null;state.messages=[];state.toolEvents=[];state.mcpSelected=[]}await refreshData();closeDialog();shell();toast('Conversation deleted.');break;
 case 'chat-history':modal('Saved conversations',`${(state.data.chats||[]).filter(c=>c.serverId===sid()).map(c=>`<div class="history-item"><button type="button" data-action="open-chat" data-id="${esc(c.id)}">${esc(c.title||'Untitled')}<small>${esc(c.model)} · ${date(c.updatedAt)}</small></button>${actionIcon('Delete conversation','delete-chat','trash',`data-id="${esc(c.id)}"`,true)}</div>`).join('')||'<p class="muted small">No saved conversations yet.</p>'}`);break;
 case 'chat-options':chatOptions();break;
 case 'delete-preset':state.presets.splice(index,1);saveLocal('spark-presets',state.presets);chatOptions();break;
 case 'export-chat':exportChat();break;
 case 'copy-message':{const msg=state.messages.filter(m=>m.role==='user'||m.role==='assistant')[index];await copyText(msg?.content||'');break}
 case 'attach-file':$('#chat-file')?.click();break;
 case 'remove-attachment':state.attachments.splice(index,1);$('#attachments').innerHTML=renderAttachments();break;
 case 'stop-chat':state.chatController?.abort();break;
 case 'install':if(state.installPrompt){await state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null}else modal('Install Spark Manager','<p class="muted small">Open this workspace over HTTPS or localhost. In Chrome or Edge, choose <strong>Install app</strong> from the browser menu. On iPhone, use Safari’s Share menu and choose <strong>Add to Home Screen</strong>.</p>');break;
 case 'logout':if(state.streaming)state.chatController?.abort();await api('/api/logout',{});state.authenticated=false;state.csrf=null;state.data=null;state.messages=[];state.toolEvents=[];state.mcpSelected=[];state.systemPrompt='';state.attachments=[];renderLogin();break;
}}
async function submit(form){if(form.getAttribute('id')==='chat-form')return sendChat(form);const values=Object.fromEntries(new FormData(form));const submitButton=form.querySelector('[type=submit]');if(submitButton)submitButton.disabled=true;form.querySelector('.form-error')?.remove();try{switch(form.getAttribute('id')){
 case 'mcp-form':await saveMcpForm(values);await refreshData();closeDialog();shell();toast('MCP connection saved.');break;
 case 'mcp-select-form':state.mcpSelected=new FormData(form).getAll('mcpServerIds').filter(id=>mcpServers().some(s=>s.id===id&&s.enabled));closeDialog();shell();toast(state.mcpSelected.length?'MCP connections selected. Each tool call needs approval.':'MCP tools are off.');break;
 case 'login-form':{const session=await api('/api/login',{password:values.password});state.authenticated=true;state.csrf=session.csrf;await refresh(true);break}
 case 'pull-form':await startJob({type:'pull',model:values.model.trim()});break;
 case 'copy-form':await api('/api/copy',{serverId:sid(),source:values.source,destination:values.destination.trim()});closeDialog();await refresh(true);toast('Model copied.');break;
 case 'create-form':{let parameters;try{parameters=values.parameters.trim()?JSON.parse(values.parameters):undefined}catch{throw Error('Parameters must be valid JSON.')}if(parameters&&(Array.isArray(parameters)||typeof parameters!=='object'))throw Error('Parameters must be a JSON object.');await startJob({type:'create',model:values.model.trim(),from:values.from,system:values.system||undefined,parameters,template:values.template||undefined,quantize:values.quantize||undefined});break}
 case 'import-form':await startJob({type:'import',model:values.model.trim(),path:values.path,system:values.system||undefined});break;
 case 'benchmark-form':await startJob({type:'benchmark',model:values.model,prompt:values.prompt});break;
 case 'settings-form':{const settings=await api('/api/settings',{title:values.title.trim(),subtitle:values.subtitle.trim()});state.branding={...state.branding,...settings};await refreshData();shell();toast('Workspace content saved.');break}
 case 'server-form':await api('/api/servers',{id:values.id||undefined,name:values.name.trim(),url:values.url.trim()});closeDialog();await refreshData();shell();toast('Server connection saved.');break;
 case 'bookmark-form':{const item={model:values.model.trim(),note:values.note.trim()};if(values.index==='')state.bookmarks.push(item);else state.bookmarks[Number(values.index)]=item;saveLocal('spark-bookmarks',state.bookmarks);closeDialog();shell();toast('Model reference saved.');break}
 case 'chat-options-form':if(!state.chatId)state.systemPrompt=values.system;state.chatOptions={temperature:Number(values.temperature),num_ctx:Number(values.num_ctx)};if(values.presetName.trim()){const item={name:values.presetName.trim(),system:values.system};const i=state.presets.findIndex(p=>p.name===item.name);if(i<0)state.presets.push(item);else state.presets[i]=item;saveLocal('spark-presets',state.presets)}closeDialog();toast('Chat options saved.');break;
}}catch(error){formError(form,error)}finally{if(submitButton)submitButton.disabled=false}}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action],[data-page]');if(!target)return;try{if(target.dataset.page){closeDialog();await navigate(target.dataset.page)}else await action(target)}catch(error){target.disabled=false;toast(error.message,true)}});
document.addEventListener('submit',event=>{event.preventDefault();submit(event.target)});
document.addEventListener('input',event=>{if(event.target.id==='model-search'){state.modelSearch=event.target.value;const old=$('#model-search');const caret=old.selectionStart;shell();const field=$('#model-search');field.focus();field.setSelectionRange(caret,caret)}});
document.addEventListener('change',async event=>{try{if(event.target.id==='mcp-transport')updateMcpTransport();if(event.target.id==='active-server')await selectServer(event.target.value);if(event.target.id==='model-sort'){state.modelSort=event.target.value;shell()}if(event.target.id==='chat-model')state.chatModel=event.target.value;if(event.target.id==='chat-file')await attachFiles([...event.target.files]);if(event.target.id==='preset-select'&&event.target.value!=='')$('#chat-system').value=state.presets[Number(event.target.value)].system}catch(error){toast(error.message,true)}});
document.addEventListener('keydown',event=>{if(event.target.id==='chat-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();if(!state.streaming)$('#chat-form').requestSubmit()}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages.includes(p)&&p!==state.page)navigate(p)});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();state.installPrompt=event});
window.addEventListener('offline',()=>toast('Connection lost. Reconnect to use your Spark.',true));
window.addEventListener('online',()=>{toast('Connection restored.');refresh(true)});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const box=$('#dialog').getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)closeDialog()}});
async function boot(){try{const session=await api('/api/session');state.authenticated=session.authenticated;state.csrf=session.csrf;state.branding={...state.branding,...session.branding};if(state.authenticated)await refresh(true);else renderLogin()}catch(error){$('#app').innerHTML=`<div class="offline-shell"><span class="brand-mark">S<span>↗</span></span><h1>Your Spark is out of reach</h1><p>${esc(error.message)} Reconnect to the manager host and try again.</p>${btn('Try again','reload','refresh','primary')}</div>`}}
boot();setInterval(()=>{if(document.visibilityState==='visible'&&state.authenticated&&!state.streaming)refresh()},15000);
setInterval(async()=>{if(!state.authenticated||state.streaming||document.visibilityState!=='visible'||!['downloads','benchmark','overview'].includes(state.page)||$('#dialog').open)return;try{state.data.jobs=await api('/api/jobs');if(state.page==='benchmark')updateBenchmarkJobs();else if(document.activeElement?.tagName!=='INPUT'&&document.activeElement?.tagName!=='TEXTAREA')shell()}catch{}},3000);
if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function mcpServers(){return state.data?.mcpServers||[]}
function structuredText(value){return typeof value==='string'?value:JSON.stringify(value??{},null,2)}
function mcpPage(){const list=mcpServers();return `${header('MCP connections','Connect tools to your models. Choose connections in Chat and review each requested call.',btn('Add connection','mcp-add','plus','primary'),'DGX SPARK / MODEL CONTEXT PROTOCOL')}<div class="alert info">${icon('shield')}<p>MCP tools are off by default in Chat. Selecting a connection gives the model its tool descriptions. Every requested tool call waits for your approval before the manager executes it.</p></div><div class="panel"><div class="panel-head"><h2>Configured connections</h2><span class="hint">${list.filter(s=>s.enabled).length} enabled · ${list.length} total</span></div>${list.length?list.map(s=>{const test=state.mcpTests[s.id];return `<article class="mcp-row"><div class="mcp-row-main"><div class="flex wrap"><strong>${esc(s.name)}</strong><span class="tag ${s.enabled?'lime':''}">${s.enabled?'Enabled':'Disabled'}</span><span class="tag">${s.transport==='stdio'?'stdio':'Streamable HTTP'}</span></div><div class="mcp-target mono">${esc(s.transport==='stdio'?s.command:s.url)}</div>${s.transport==='stdio'?`<p class="help">${esc((s.args||[]).join(' '))}${s.cwd?` · ${esc(s.cwd)}`:''}</p>`:''}<p class="help">${s.hasToken?'Bearer token saved. ':''}${s.envKeys?.length?`Environment keys saved: ${esc(s.envKeys.join(', '))}. `:''}${test?test.loading?'Testing connection…':test.error?`<span class="danger-text">${esc(test.error)}</span>`:`<span class="lime">Connected</span> · ${esc(test.serverInfo?.name||'MCP service')} · ${test.tools?.length||0} tools`:'Connection has not been tested in this browser.'}</p></div><div class="mcp-row-actions">${btn(s.enabled?'Disable':'Enable','mcp-toggle',s.enabled?'stop':'check','small',`data-id="${esc(s.id)}"`)}${btn(test?.loading?'Testing…':'Test connection','mcp-test','bolt','small',`data-id="${esc(s.id)}"${test?.loading?' disabled':''}`)}${btn('View tools','mcp-tools','mcp','small',`data-id="${esc(s.id)}"`)}${actionIcon('Edit '+s.name,'mcp-edit','edit',`data-id="${esc(s.id)}"`)}${actionIcon('Delete '+s.name,'mcp-delete','trash',`data-id="${esc(s.id)}"`,true)}</div></article>`}).join(''):empty('Connect your first MCP service','Add an existing Streamable HTTP endpoint or a stdio process installed on the manager host.','','mcp')}</div><div class="two-col mcp-notes"><div class="panel"><div class="panel-body"><h3>Streamable HTTP</h3><p class="help">Use the service’s MCP endpoint URL. The manager connects directly to that address. An optional bearer token is stored on the manager and never read back into this page.</p></div></div><div class="panel"><div class="panel-body"><h3>stdio on your Spark</h3><p class="help">Use the absolute path of an installed executable, a JSON array of arguments, and optional working directory or environment values. Testing starts that configured process on the manager host.</p></div></div></div>`}
function mcpDialog(existing){modal(existing?'Edit MCP connection':'Add MCP connection',`<form id="mcp-form">${existing?`<input type="hidden" name="id" value="${esc(existing.id)}">`:''}<div class="form-group"><label for="mcp-name">Connection name</label><input id="mcp-name" name="name" class="field" value="${esc(existing?.name||'')}" required maxlength="80" placeholder="My tools"></div><div class="form-grid"><div class="form-group"><label for="mcp-transport">Transport</label><select id="mcp-transport" name="transport" class="field"><option value="http"${existing?.transport!=='stdio'?' selected':''}>Streamable HTTP</option><option value="stdio"${existing?.transport==='stdio'?' selected':''}>stdio process</option></select></div><div class="form-group"><label class="check-line mcp-enabled"><input id="mcp-enabled" name="enabled" type="checkbox" ${existing?.enabled?'checked':''}> Enable this connection</label><p class="help">Available for explicit selection in Chat.</p></div></div><div id="mcp-http-fields"><div class="form-group"><label for="mcp-url">MCP endpoint URL</label><input id="mcp-url" name="url" class="field mono" type="url" value="${esc(existing?.url||'')}" placeholder="http://127.0.0.1:8000/mcp"><p class="help">Use the exact Streamable HTTP endpoint, usually ending in /mcp.</p></div><div class="form-group"><label for="mcp-token">Bearer token (optional)</label><input id="mcp-token" name="bearerToken" class="field" type="password" autocomplete="new-password" placeholder="${existing?.hasToken?'A token is saved. Leave blank to keep it.':'Optional service token'}"><p class="help">${existing?.hasToken?'The saved token is never shown. Enter a new value to replace it.':'Only sent to this configured MCP service.'}</p><label class="check-line" style="margin-top:9px"><input type="checkbox" name="clearToken" id="mcp-clear-token"> Clear the saved bearer token</label></div></div><div id="mcp-stdio-fields"><div class="form-group"><label for="mcp-command">Executable absolute path</label><input id="mcp-command" name="command" class="field mono" value="${esc(existing?.command||'')}" placeholder="/usr/bin/node"><p class="help">An installed executable on the manager host. Arguments are passed directly; no shell command is evaluated.</p></div><div class="form-group"><label for="mcp-args">Arguments (JSON array)</label><textarea id="mcp-args" name="args" class="field mono" rows="3" placeholder='["/path/to/mcp-server.mjs"]'>${esc(JSON.stringify(existing?.args||[]))}</textarea></div><div class="form-group"><label for="mcp-cwd">Working directory (optional)</label><input id="mcp-cwd" name="cwd" class="field mono" value="${esc(existing?.cwd||'')}" placeholder="/absolute/path/to/workspace"><p class="help">Leave blank to use the manager’s dedicated MCP workspace.</p></div><div class="form-group"><label for="mcp-env">Environment values (JSON object, optional)</label><textarea id="mcp-env" name="env" class="field mono" rows="3" autocomplete="off" spellcheck="false" placeholder='{"API_KEY":"new-secret-value"}'></textarea><p class="help">${existing?.envKeys?.length?`Saved keys: ${esc(existing.envKeys.join(', '))}. `:''}Values are never shown. Leave blank to keep existing values; entering an object replaces them.</p><label class="check-line" style="margin-top:9px"><input type="checkbox" name="clearEnv" id="mcp-clear-env"> Clear all saved environment values</label></div></div><p class="help">A stdio process runs with the manager service’s permissions. Choose the executable and arguments you intend to run.</p><div class="form-footer">${btn('Cancel','close-dialog')}<button type="submit" class="btn primary">${icon('check')}Save connection</button></div></form>`,true);updateMcpTransport()}
function updateMcpTransport(){const transport=$('#mcp-transport')?.value;if(!transport)return;for(const [id,active] of [['mcp-http-fields',transport==='http'],['mcp-stdio-fields',transport==='stdio']]){const group=document.getElementById(id);group.hidden=!active;group.querySelectorAll('input,textarea').forEach(el=>{el.disabled=!active;el.required=active&&['mcp-url','mcp-command'].includes(el.id)})}}
async function saveMcpForm(v){const payload={id:v.id||undefined,name:v.name.trim(),transport:v.transport,enabled:v.enabled==='on'};if(v.transport==='http'){payload.url=v.url.trim();if(v.clearToken==='on')payload.bearerToken='';else if(v.bearerToken)payload.bearerToken=v.bearerToken}else{payload.command=v.command.trim();payload.cwd=v.cwd.trim()||undefined;try{payload.args=v.args.trim()?JSON.parse(v.args):[]}catch{throw Error('Arguments must be a valid JSON array.')}if(!Array.isArray(payload.args)||payload.args.some(arg=>typeof arg!=='string'))throw Error('Arguments must be a JSON array of strings.');if(v.clearEnv==='on')payload.env={};else if(v.env.trim()){try{payload.env=JSON.parse(v.env)}catch{throw Error('Environment values must be a valid JSON object.')}if(!payload.env||Array.isArray(payload.env)||typeof payload.env!=='object'||Object.values(payload.env).some(value=>typeof value!=='string'))throw Error('Environment values must be a JSON object containing strings.')}}await api('/api/mcp/servers',payload)}
function mcpConfigPayload(s,enabled){return {id:s.id,name:s.name,transport:s.transport,enabled,url:s.url,command:s.command,args:s.args,cwd:s.cwd}}
async function toggleMcp(id){const connection=mcpServers().find(s=>s.id===id);if(!connection)return;await api('/api/mcp/servers',mcpConfigPayload(connection,!connection.enabled));if(connection.enabled)state.mcpSelected=state.mcpSelected.filter(value=>value!==id);await refreshData();shell();toast(connection.enabled?'MCP connection disabled.':'MCP connection enabled. Select it in Chat to use its tools.')}
async function testMcp(id,button){button.disabled=true;state.mcpTests[id]={loading:true};if(state.page==='mcp')shell();try{const result=await api(`/api/mcp/servers/${encodeURIComponent(id)}/test`,{});state.mcpTests[id]={...result,loading:false};state.mcpTools[id]=result.tools||[];toast(`MCP connected. ${result.tools?.length||0} tools available.`)}catch(error){state.mcpTests[id]={error:error.message,loading:false};toast(error.message,true)}finally{if(state.page==='mcp')shell()}}
async function showMcpTools(id,button){button.disabled=true;const connection=mcpServers().find(s=>s.id===id);modal(`${connection?.name||'MCP'} tools`,'<div class="loading-panel"><span class="spinner"></span>Reading tool definitions…</div>',true);try{const data=await api(`/api/mcp/servers/${encodeURIComponent(id)}/tools`);state.mcpTools[id]=data.tools||[];modal(`${connection?.name||'MCP'} tools`,data.tools?.length?`<div class="mcp-tools-list">${data.tools.map(tool=>`<article class="mcp-tool-definition"><h3 class="mono">${esc(tool.name)}</h3><p class="help">${esc(tool.description||'No description provided by this service.')}</p><details><summary class="help">Input schema</summary><pre>${esc(structuredText(tool.inputSchema))}</pre></details></article>`).join('')}</div><p class="help">Definitions come from this MCP service. Tool execution still requires approval in Chat.</p>`:empty('No tools returned','This service did not expose any tools.','','mcp'),true)}catch(error){modal(`${connection?.name||'MCP'} tools`,`<p class="form-error" role="alert">${esc(error.message)}</p>`,true)}finally{if(button.isConnected)button.disabled=false}}
function chatMcpBar(){const selected=state.mcpSelected.filter(id=>mcpServers().some(s=>s.id===id&&s.enabled));return `<div class="chat-mcp-bar"><span class="flex">${icon('mcp')}<span>${selected.length?`${selected.length} MCP connection${selected.length===1?'':'s'} selected · approval required`:'Tools are off'}</span></span><button type="button" class="btn ghost small" data-action="mcp-select" ${state.streaming?'disabled':''}>Choose MCP</button></div>`}
function mcpSelectionDialog(){const enabled=mcpServers().filter(s=>s.enabled);modal('Choose MCP connections',`<p class="help" style="margin-bottom:18px">The model receives tool descriptions from selected connections. Review the arguments and approve or deny each requested tool call before it runs.</p>${enabled.length?`<form id="mcp-select-form"><div class="mcp-check-list">${enabled.map(s=>`<label class="mcp-check-option"><input type="checkbox" name="mcpServerIds" value="${esc(s.id)}" ${state.mcpSelected.includes(s.id)?'checked':''}><span><strong>${esc(s.name)}</strong><small>${s.transport==='stdio'?'stdio':'Streamable HTTP'} · ${esc(s.transport==='stdio'?s.command:s.url)}</small></span></label>`).join('')}</div><p class="help">Leave every connection unchecked to keep tools off.</p><div class="form-footer">${btn('Cancel','close-dialog')}<button class="btn primary" type="submit">Save selection</button></div></form>`:empty('No enabled MCP connections','Add and enable a connection on the MCP connections page first.',`<button type="button" class="btn primary" data-page="mcp">${icon('mcp')}Manage connections</button>`,'mcp')}`)}
function recordToolEvent(event){const index=state.toolEvents.findIndex(item=>item.id===event.id);if(index<0)state.toolEvents.push({...event,createdAt:new Date().toISOString()});else state.toolEvents[index]={...state.toolEvents[index],...event,deciding:false}}
function renderToolEvents(){if(!state.toolEvents.length)return '';return `<div class="tool-event-log" aria-label="MCP tool activity">${state.toolEvents.map(event=>{const pending=state.streaming&&event.status==='pending';return `<article class="tool-event ${pending?'pending':''}" data-tool-id="${esc(event.id)}"><div class="tool-event-head"><div class="flex">${icon('mcp')}<strong class="mono">${esc(event.name||'Tool call')}</strong></div><span class="tag ${event.status==='completed'?'lime':''}">${esc(event.deciding?'Submitting decision':event.status||'pending')}</span></div><p class="help">${esc(event.serverName||'MCP connection')}${pending?' · Review this request before allowing it to run.':''}</p>${event.arguments!==undefined?`<details ${pending?'open':''}><summary class="help">Arguments</summary><pre>${esc(structuredText(event.arguments))}</pre></details>`:''}${event.content!==undefined?`<details><summary class="help">${event.isError?'Error output':'Tool output'}</summary><pre>${esc(structuredText(event.content))}</pre></details>`:''}${pending?`<p class="help">Tools can read or change data on the connected service. Check the tool name and arguments.</p><div class="tool-decision-actions"><button type="button" class="btn ghost" data-action="tool-deny" data-id="${esc(event.id)}" ${event.deciding?'disabled':''}>${icon('close')}Deny tool call</button><button type="button" class="btn primary" data-action="tool-approve" data-id="${esc(event.id)}" ${event.deciding?'disabled':''}>${icon('check')}Approve tool call</button></div>`:''}</article>`}).join('')}</div>`}
async function decideTool(callId,approved,button){const event=state.toolEvents.find(item=>item.id===callId);if(!state.streaming||!state.chatId||event?.status!=='pending'||event.deciding)return;event.deciding=true;const area=$('#chat-messages');if(area)area.innerHTML=renderMessages();try{await api(`/api/chat/${encodeURIComponent(state.chatId)}/tool-decision`,{callId,approved});event.status=approved?'running':'denied';event.deciding=false;if($('#chat-messages'))$('#chat-messages').innerHTML=renderMessages();scrollChat()}catch(error){event.deciding=false;if($('#chat-messages'))$('#chat-messages').innerHTML=renderMessages();toast(error.message,true)}}
